    'c.brick.s': { m: "في آخر اليوم توجد مونة على وجه الطوب. ماذا تفعل؟", f: "في آخر اليوم توجد مونة على وجه الطوب. ماذا تفعلين؟", x: "في آخر اليوم توجد مونة على وجه الطوب. ما التصرف الصحيح؟" }, // nieuw, nalezen // nagelezen AI 22 nov
