    'c.pruning.b': { m: "قلّم بمقصّ حادّ ونظيف. القطع النظيف يلتئم بسرعة؛ والغصن الممزّق يمرض. اقطع فوق برعم أو غصن جانبي مباشرة، ولا تترك قطعة طويلة. أزِل الأغصان الميتة والمكسورة أولاً. أبعِد يدك الأخرى عن الشفرات. البس القفازات: بعض النباتات لها أشواك، أو تجعل جلدك أحمر. نظّف المقصّ بعد العمل.", f: "قلّمي بمقصّ حادّ ونظيف. القطع النظيف يلتئم بسرعة؛ والغصن الممزّق يمرض. اقطعي فوق برعم أو غصن جانبي مباشرة، ولا تتركي قطعة طويلة. أزيلي الأغصان الميتة والمكسورة أولاً. أبعدي يدك الأخرى عن الشفرات. البسي القفازات: بعض النباتات لها أشواك، أو تجعل جلدك أحمر. نظّفي المقصّ بعد العمل.", x: "التقليم يكون بمقصّ حادّ ونظيف. القطع النظيف يلتئم بسرعة؛ والغصن الممزّق يمرض. القطع يكون فوق برعم أو غصن جانبي مباشرة، بدون ترك قطعة طويلة. إزالة الأغصان الميتة والمكسورة أولاً. اليد الأخرى تبقى بعيدة عن الشفرات. لبس القفازات: بعض النباتات لها أشواك، أو تجعل الجلد أحمر. تنظيف المقصّ بعد العمل." }, // nieuw, nalezen
    'c.pruning.p': "أين يجب أن أقطع؟", // nieuw, nalezen
    'c.pruning.s': { m: "مقصّ التقليم عندك غير حادّ. إنه يمزّق الأغصان. ماذا تفعل؟", f: "مقصّ التقليم عندك غير حادّ. إنه يمزّق الأغصان. ماذا تفعلين؟", x: "مقصّ التقليم غير حادّ. إنه يمزّق الأغصان. ما التصرف الصحيح؟" }, // nieuw, nalezen
