    's.firstaid.2': { m: "أحضر جهاز AED من الاستقبال.", f: "أحضري جهاز AED من الاستقبال.", x: "إحضار جهاز AED من الاستقبال." }, // nieuw, nalezen
    's.firstaid.3': "إنه لا يتنفّس. سأبدأ الإنعاش.", // nieuw, nalezen
