    'c.wastesafety.a': { m: "اغسل الجرح جيداً. وأخبرني.", f: "اغسلي الجرح جيداً. وأخبريني.", x: "غسل الجرح جيداً. وإخباري بذلك." }, // nieuw, nalezen
    'c.wastesafety': { m: "لا تضغط على الكيس أبداً", f: "لا تضغطي على الكيس أبداً", x: "الضغط على الكيس ممنوع أبداً" }, // nieuw, nalezen
    'c.wastesafety.b': { m: "كيس القمامة قد يكون فيه زجاج أو سكاكين أو إبر. لذلك لا تضغط الكيس أبداً على جسمك، ولا تعصره أبداً، ولا تحمله أبداً على ساقك: امسكه من الأعلى، بعيداً عنك. البس قفازاتك. ارفع والركبتان مثنيتان والظهر مستقيم، وادفع الحاوية، لا تحملها. هل وخزك شيء أو جرحك؟ اغسل الجرح جيداً بالماء، وأخبر مشرفك في اليوم نفسه.", f: "كيس القمامة قد يكون فيه زجاج أو سكاكين أو إبر. لذلك لا تضغطي الكيس أبداً على جسمك، ولا تعصريه أبداً، ولا تحمليه أبداً على ساقك: امسكيه من الأعلى، بعيداً عنك. البسي قفازاتك. ارفعي والركبتان مثنيتان والظهر مستقيم، وادفعي الحاوية، لا تحمليها. هل وخزكِ شيء أو جرحكِ؟ اغسلي الجرح جيداً بالماء، وأخبري مشرفك في اليوم نفسه.", x: "كيس القمامة قد يكون فيه زجاج أو سكاكين أو إبر. لذلك ضغط الكيس على الجسم ممنوع أبداً، وعصره ممنوع أبداً، وحمله على الساق ممنوع أبداً: يُمسك من الأعلى، بعيداً عن الجسم. لبس القفازات. الرفع والركبتان مثنيتان والظهر مستقيم، والحاوية تُدفع، لا تُحمل. وخزة أو جرح من شيء؟ غسل الجرح جيداً بالماء، وإخبار المشرف في اليوم نفسه." }, // nieuw, nalezen
