    'c.hazardous.a': { m: "لا أعرف. ضعها جانباً.", f: "لا أعرف. ضعيها جانباً.", x: "لا أعرف. توضع جانباً." }, // nieuw, nalezen
    'c.hazardous': { m: "غير معروف؟ لا تفتحه، ولا تشمّه", f: "غير معروف؟ لا تفتحيه، ولا تشمّيه", x: "غير معروف؟ لا فتح، ولا شمّ" }, // nieuw, nalezen
    'c.hazardous.b': { m: "النفايات الكيميائية، مثل الدهان والزيت ومواد التنظيف والبطاريات وعلب الرشّ، قد تحرق أو تسمّم أو تنفجر. ابحث عن رموز الخطر. البس القفازات ونظارات السلامة. لا تفتح أبداً قنينة لتشمّ ما فيها، ولا تخلط المواد أبداً. أبقِ القنينة التي تسرّب واقفة، وضعها في صينية. الأسبستوس لا يُقبل إلا إذا كان مغلّفاً جيداً: لا تكسره أبداً، ولا تخرجه من الغلاف. القواعد تختلف من شركة لأخرى: اسأل مشرفك عن القواعد في مكان عملك.", f: "النفايات الكيميائية، مثل الدهان والزيت ومواد التنظيف والبطاريات وعلب الرشّ، قد تحرق أو تسمّم أو تنفجر. ابحثي عن رموز الخطر. البسي القفازات ونظارات السلامة. لا تفتحي أبداً قنينة لتشمّي ما فيها، ولا تخلطي المواد أبداً. أبقي القنينة التي تسرّب واقفة، وضعيها في صينية. الأسبستوس لا يُقبل إلا إذا كان مغلّفاً جيداً: لا تكسريه أبداً، ولا تخرجيه من الغلاف. القواعد تختلف من شركة لأخرى: اسألي مشرفك عن القواعد في مكان عملك.", x: "النفايات الكيميائية، مثل الدهان والزيت ومواد التنظيف والبطاريات وعلب الرشّ، قد تحرق أو تسمّم أو تنفجر. البحث عن رموز الخطر. لبس القفازات ونظارات السلامة. فتح قنينة لشمّ ما فيها ممنوع أبداً، وخلط المواد ممنوع أبداً. القنينة التي تسرّب تبقى واقفة، وتوضع في صينية. الأسبستوس لا يُقبل إلا إذا كان مغلّفاً جيداً: كسره ممنوع أبداً، وإخراجه من الغلاف ممنوع. القواعد تختلف من شركة لأخرى: السؤال عن قواعد مكان العمل يكون عند المشرف." }, // nieuw, nalezen
