    'c.playtime': { m: "العب بأمان: انظر، عُدّ، افحص", f: "العبي بأمان: انظري، عُدّي، افحصي", x: "اللعب بأمان: النظر، العدّ، الفحص" }, // nieuw, nalezen
    'c.playtime.b': { m: "الأطفال يتعلّمون باللعب، لذلك دعهم يجرّبون الأشياء. لكن أبقِهم دائماً أمام عينيك، في الخارج أيضاً. عُدّ الأطفال عندما تخرجون وعندما تعودون إلى الداخل. افحص ساحة اللعب أولاً: هل البوّابة مغلقة، هل يوجد زجاج أو قمامة؟ الألعاب ذات القطع الصغيرة ليست للأطفال تحت ثلاث سنوات: قد يختنقون بها. نظّف كثيراً الألعاب التي تدخل الفم. القواعد تختلف من شركة لأخرى: اسأل مشرفك عن القواعد في مكان عملك.", f: "الأطفال يتعلّمون باللعب، لذلك دعيهم يجرّبون الأشياء. لكن أبقيهم دائماً أمام عينيك، في الخارج أيضاً. عُدّي الأطفال عندما تخرجون وعندما تعودون إلى الداخل. افحصي ساحة اللعب أولاً: هل البوّابة مغلقة، هل يوجد زجاج أو قمامة؟ الألعاب ذات القطع الصغيرة ليست للأطفال تحت ثلاث سنوات: قد يختنقون بها. نظّفي كثيراً الألعاب التي تدخل الفم. القواعد تختلف من شركة لأخرى: اسألي مشرفك عن القواعد في مكان عملك.", x: "الأطفال يتعلّمون باللعب، لذلك يُتركون يجرّبون الأشياء. لكن يبقون دائماً تحت النظر، في الخارج أيضاً. عدّ الأطفال عند الخروج وعند العودة إلى الداخل. فحص ساحة اللعب أولاً: هل البوّابة مغلقة، هل يوجد زجاج أو قمامة؟ الألعاب ذات القطع الصغيرة ليست للأطفال تحت ثلاث سنوات: قد يختنقون بها. تنظيف الألعاب التي تدخل الفم كثيراً. القواعد تختلف من شركة لأخرى: السؤال عن قواعد مكان العمل يكون عند المشرف." }, // nieuw, nalezen
    'c.playtime.p': "هل الجميع هنا؟", // nieuw, nalezen
    'c.playtime.s': { m: "تعود إلى الداخل من ساحة اللعب. تعدّ الأطفال: ينقص طفل واحد. ماذا تفعل؟", f: "تعودين إلى الداخل من ساحة اللعب. تعدّين الأطفال: ينقص طفل واحد. ماذا تفعلين؟", x: "العودة إلى الداخل من ساحة اللعب. في العدّ ينقص طفل واحد. ما التصرف الصحيح؟" }, // nieuw, nalezen
