    'c.bill': { m: "المال على الطاولة: عُدّه مرتين", f: "المال على الطاولة: عُدّيه مرتين", x: "المال على الطاولة: العدّ مرتين" }, // nieuw, nalezen
    'c.bill.b': { m: "عندما يدفع الضيف، قل المبلغ بوضوح ودع الضيف يرى جهاز الدفع. مع النقود، عُدّ المال عندما تستلمه، ومرة أخرى عندما تعطي الباقي. المال يذهب إلى صندوق الدفع أو إلى محفظة الخدمة الخاصة بك، ولا يذهب أبداً إلى جيبك. البقشيش (fooi) يذهب إلى حيث تقول شركتك، مثلاً في علبة البقشيش. هل غادر ضيف دون أن يدفع؟ لا تركض وراءه: أخبر مديرك. القواعد تختلف من شركة لأخرى: اسأل مشرفك عن القواعد في مكان عملك.", f: "عندما يدفع الضيف، قولي المبلغ بوضوح ودعي الضيف يرى جهاز الدفع. مع النقود، عُدّي المال عندما تستلمينه، ومرة أخرى عندما تعطين الباقي. المال يذهب إلى صندوق الدفع أو إلى محفظة الخدمة الخاصة بك، ولا يذهب أبداً إلى جيبك. البقشيش (fooi) يذهب إلى حيث تقول شركتك، مثلاً في علبة البقشيش. هل غادر ضيف دون أن يدفع؟ لا تركضي وراءه: أخبري مديرك. القواعد تختلف من شركة لأخرى: اسألي مشرفك عن القواعد في مكان عملك.", x: "عندما يدفع الضيف، قول المبلغ بوضوح وترك الضيف يرى جهاز الدفع. مع النقود، عدّ المال عند استلامه، ومرة أخرى عند إعطاء الباقي. المال يذهب إلى صندوق الدفع أو إلى محفظة الخدمة، ولا يذهب أبداً إلى الجيب الخاص. البقشيش (fooi) يذهب إلى حيث تقول الشركة، مثلاً في علبة البقشيش. هل غادر ضيف دون أن يدفع؟ الركض وراءه ممنوع: إخبار المدير. القواعد تختلف من شركة لأخرى: السؤال عن قواعد مكان العمل يكون عند المشرف." }, // nieuw, nalezen
    'c.bill.p': "المبلغ خمسة وأربعون يورو، من فضلك.", // nieuw, nalezen
    'c.bill.s': { m: "ضيف يعطيك مالاً ويقول: “المبلغ صحيح.” لم تعدّه. ماذا تفعل؟", f: "ضيف يعطيك مالاً ويقول: “المبلغ صحيح.” لم تعدّيه. ماذا تفعلين؟", x: "ضيف يعطي مالاً ويقول: “المبلغ صحيح.” المال لم يُعدّ بعد. ما التصرف الصحيح؟" }, // nieuw, nalezen
