    'c.liftaids.q': { m: "هل تستطيع أن تقلب السيدة وحدك؟", f: "هل تستطيعين أن تقلبي السيدة وحدك؟", x: "هل يمكن قلب السيدة بدون مساعدة؟" }, // nieuw, nalezen
    'c.liftaids.a': "مع ملاءة الانزلاق أستطيع. سأحضرها.", // nieuw, nalezen
    'c.liftaids': { m: "دع الأداة ترفع عنك", f: "دعي الأداة ترفع عنك", x: "الرفع بالأداة، لا بالجسم" }, // nieuw, nalezen
    'c.liftaids.b': { m: "قبل أن تستعمل الرافعة، افحصها: هل البطارية مشحونة، وهل حزام الرفع بالمقاس الصحيح وغير ممزّق؟ شدّ الفرامل على السرير والكرسي المتحرّك. ارفع السرير إلى ارتفاع وركيك، حتى لا تنحني. أخبر المستفيد من الرعاية بكل خطوة. خطة الرعاية تذكر أي أداة يحتاجها المستفيد. هل الأداة مكسورة أو غير موجودة؟ لا تعمل بدونها: أبلغ عن ذلك، واطلب من زميل أن يساعدك. لم يشرح لك أحد كيف تعمل الأداة؟ اسأل قبل أن تبدأ. القواعد تختلف من شركة لأخرى: اسأل مشرفك عن القواعد في مكان عملك.", f: "قبل أن تستعملي الرافعة، افحصيها: هل البطارية مشحونة، وهل حزام الرفع بالمقاس الصحيح وغير ممزّق؟ شدّي الفرامل على السرير والكرسي المتحرّك. ارفعي السرير إلى ارتفاع وركيك، حتى لا تنحني. أخبري المستفيد من الرعاية بكل خطوة. خطة الرعاية تذكر أي أداة يحتاجها المستفيد. هل الأداة مكسورة أو غير موجودة؟ لا تعملي بدونها: أبلغي عن ذلك، واطلبي من زميل أن يساعدك. لم يشرح لك أحد كيف تعمل الأداة؟ اسألي قبل أن تبدئي. القواعد تختلف من شركة لأخرى: اسألي مشرفك عن القواعد في مكان عملك.", x: "قبل استعمال الرافعة، فحصها: هل البطارية مشحونة، وهل حزام الرفع بالمقاس الصحيح وغير ممزّق؟ شدّ الفرامل على السرير والكرسي المتحرّك. رفع السرير إلى ارتفاع الوركين، حتى لا يكون انحناء. إخبار المستفيد من الرعاية بكل خطوة. خطة الرعاية تذكر أي أداة يحتاجها المستفيد. هل الأداة مكسورة أو غير موجودة؟ العمل بدونها ممنوع: الإبلاغ عن ذلك، وطلب المساعدة من زميل. طريقة عمل الأداة غير مشروحة؟ السؤال قبل البدء. القواعد تختلف من شركة لأخرى: السؤال عن قواعد مكان العمل يكون عند المشرف." }, // nieuw, nalezen
